DELIMITER ;;
/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER `TRG_VALIDAR_TIPO_DETALLE` BEFORE INSERT ON `detalles_reservacion` FOR EACH ROW BEGIN

    DECLARE v_tipo_reserva INT;



    -- Obtener el tipo de reserva de la reservación padre

    SELECT Tipo_Reserva_ID INTO v_tipo_reserva

    FROM Reservacion

    WHERE ID = NEW.Reservacion_ID;



    -- Tipo 1 (Aérea): solo permite vuelos (Tipo_Detalle_ID = 1)

    IF v_tipo_reserva = 1 AND NEW.Tipo_Detalle_ID != 1 THEN

        SIGNAL SQLSTATE '45000'

        SET MESSAGE_TEXT = 'Reservación aérea solo admite detalles de vuelo';

    END IF;



    -- Tipo 2 (Hotelera): solo permite hoteles (Tipo_Detalle_ID = 2)

    IF v_tipo_reserva = 2 AND NEW.Tipo_Detalle_ID != 2 THEN

        SIGNAL SQLSTATE '45000'

        SET MESSAGE_TEXT = 'Reservación hotelera solo admite detalles de hotel';

    END IF;



    -- Tipo 3 (Paquete): permite vuelo (1) y hotel (2), nada más

    IF v_tipo_reserva = 3 AND NEW.Tipo_Detalle_ID NOT IN (1, 2) THEN

        SIGNAL SQLSTATE '45000'

        SET MESSAGE_TEXT = 'Reservación paquete solo admite vuelo y hotel';

    END IF;



END */;;
DELIMITER ;
