--
-- Table structure for table `log_sesion`
--

DROP TABLE IF EXISTS `log_sesion`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `log_sesion` (
  `ID` bigint(20) NOT NULL AUTO_INCREMENT,
  `Tipo_Evento_ID` int(11) NOT NULL,
  `Usuario_ID` int(11) DEFAULT NULL,
  `Login_Intentado` varchar(150) DEFAULT NULL,
  `Exitoso` tinyint(1) NOT NULL DEFAULT 0,
  `IP_Origen` varchar(45) DEFAULT NULL,
  `User_Agent` varchar(500) DEFAULT NULL,
  `Mensaje` varchar(500) DEFAULT NULL,
  `Fecha` datetime NOT NULL DEFAULT current_timestamp(),
  PRIMARY KEY (`ID`),
  KEY `idx_fecha` (`Fecha`),
  KEY `idx_usuario_fecha` (`Usuario_ID`,`Fecha`),
  KEY `idx_tipo_fecha` (`Tipo_Evento_ID`,`Fecha`),
  KEY `idx_ip_fecha` (`IP_Origen`,`Fecha`),
  CONSTRAINT `fk_log_sesion_tipo` FOREIGN KEY (`Tipo_Evento_ID`) REFERENCES `tipo_evento_sesion` (`ID`),
  CONSTRAINT `fk_log_sesion_usuario` FOREIGN KEY (`Usuario_ID`) REFERENCES `usuario` (`ID`)
) ENGINE=InnoDB AUTO_INCREMENT=2669 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

